mapper.select:
/* printMapper.selectEmsOtbl011PrintInfoLabel : B/L 라벨 출력정보 조회 */
SELECT 
	  PRINT_FORM_CODE 
	 ,PRINT_FORM_NAME
	 ,RPT_FILE_NAME AS RPT_FILE_NAME
FROM TB_SMS_PRINT_FORM
WHERE SOLUTION = #{solution}
AND ENT_CODE = #{entCode}
AND ENT_BUSINESS_CODE = #{userEntBusinessCode}

AND RPT_FILE_NAME IN #{item}


AND PRINT_FORM_CODE = #{srchPrintFormCode}

AND USE_YN = 'Y'

ORDER BY PRINT_FORM_NAME

mapper.delete:
/* printMapper.deletePrintFormUbi : PrintFormUbi Delete */
DELETE FROM TB_SMS_PRINT_FORM_UBI
WHERE REGISTER_USER_ID =  #{userId} 
AND ENT_CODE = #{entCode}
AND ENT_BUSINESS_CODE = #{userEntBusinessCode}
AND PRINT_FORM_CODE =  #{printFormCode}

mapper.select:
/* printMapper.getPrintFormItemList : 인쇄정보 항목 가져오기 */ SELECT pf.DOC_SIZE_WIDTH , pf.DOC_SIZE_HEIGHT , pf.MARGIN_TOP , pf.MARGIN_LEFT , pf.REMARKS , pf.DISPLAY_INDEX , pfi.PRINT_FORM_CODE , pfi.CONTROL_ID , pfi.RPT_CONTROL_ID , pfi.CONTROL_NAME , pfi.MAX_LENGTH , pfi.MAX_LINE , pfi.FIXED_VALUE , pfi.LOCATION_TOP , pfi.LOCATION_LEFT , pfi.LOCATION_WIDTH , pfi.LOCATION_HEIGHT , pfi.TEXT_FONT , pfi.TEXT_FONT_SIZE , pfi.TEXT_FONT_COLOR , pfi.TEXT_BG_COLOR , pfi.TEXT_BG_COLOR_YN , pfi.TEXT_UNDERLINE , pfi.TEST_EDIT_YN , pfi.TEXT_H_ALIGNMENT , pfi.TEXT_V_ALIGNMENT , pfi.TEXT_LINK_URL , pfi.USE_YN , pfi.SEQ_NO , ISNULL(BL_MARK1_MAX_LENGTH, 0) AS BL_MARK1_MAX_LENGTH , BL_MARK1_MAX_LINE , ISNULL(BL_MARK2_MAX_LENGTH, 0) AS BL_MARK2_MAX_LENGTH , BL_MARK2_MAX_LINE
,CASE pfi.CONTROL_ID WHEN 'BARCODE' THEN '1' ELSE '2' END AS PRINT_INDEX
FROM TB_SMS_PRINT_FORM pf INNER JOIN TB_SMS_PRINT_FORM_ITEM pfi ON pf.PRINT_FORM_CODE = pfi.PRINT_FORM_CODE AND pfi.USE_YN = 'Y'
WHERE pf.PRINT_FORM_CODE = #{printFormCode}
AND pf.BOUND = #{bound}
AND pf.BOUND_TYPE = #{boundType}
ORDER BY SEQ_NO

mapper.insert:
		/* fms.awbPrint.insertPrintFormUbi */
			INSERT INTO TB_SMS_PRINT_FORM_UBI (
				  ENT_CODE
				, ENT_BUSINESS_CODE
				, REGISTER_USER_ID
   		 		, REGISTER_DATE_TIME
   		 		, SEQ_NO
				, PRINT_FORM_CODE
				, REFERENCE_NO
				, CONTROL_ID
				, CONTROL_VALUE
				, MBL_NO_BARCODE_VAL
   		 		, MBL_GWT_BARCODE_VAL
   		 		, HBL_NO_BARCODE_VAL
   		 		, HBL_GWT_BARCODE_VAL
				, RPT_CONTROL_ID
				, CONTROL_NAME   
				, DOC_SIZE_WIDTH
				, DOC_SIZE_HEIGHT 
				, MARGIN_TOP 
				, MARGIN_LEFT     
				, MAX_LENGTH 
				, MAX_LINE 
				, FIXED_VALUE 
				, LOCATION_TOP 
				, LOCATION_LEFT 
				, LOCATION_WIDTH 
				, LOCATION_HEIGHT 
				, TEXT_FONT
				, TEXT_FONT_SIZE 
				, TEXT_FONT_COLOR
				, TEXT_BG_COLOR
				, TEXT_BG_COLOR_YN 
				, TEXT_UNDERLINE 
				, TEST_EDIT_YN  
   		 		, TEXT_H_ALIGNMENT
				, TEXT_V_ALIGNMENT
				, TEXT_LINK_URL
				, REMARKS
				, DISPLAY_INDEX  
				, USE_YN
    	 		, UPDATE_USER_ID
    	 		, UPDATE_DATE_TIME
    	 		, PRINT_NO_FROM
    	 		, PRINT_NO_TO
			) VALUES

			(
				#{item.ENT_CODE}
				, #{item.ENT_BUSINESS_CODE}
				, #{item.USER_ID}
				, DATEADD(hh, ${item.GMT_TIME}, GETDATE())
				, #{item.SEQ_NO}
				, #{item.PRINT_FORM_CODE}
				, #{item.REFERENCE_NO}
				, #{item.CONTROL_ID}
				, #{item.CONTROL_VALUE}
				, #{item.MBL_NO_BARCODE_VAL}
				, #{item.MBL_GWT_BARCODE_VAL}
				, #{item.HBL_NO_BARCODE_VAL}
				, #{item.HBL_GWT_BARCODE_VAL}
				, #{item.RPT_CONTROL_ID}
				, #{item.CONTROL_NAME}
				, #{item.DOC_SIZE_WIDTH}
				, #{item.DOC_SIZE_HEIGHT}
				, #{item.MARGIN_TOP}
				, #{item.MARGIN_LEFT}
				, #{item.MAX_LENGTH}
				, #{item.MAX_LINE}
				, #{item.FIXED_VALUE}
				, #{item.LOCATION_TOP}
				, #{item.LOCATION_LEFT}
				, #{item.LOCATION_WIDTH}
				, #{item.LOCATION_HEIGHT}
				, #{item.TEXT_FONT}
				, #{item.TEXT_FONT_SIZE}
				, #{item.TEXT_FONT_COLOR}
				, #{item.TEXT_BG_COLOR}
				, #{item.TEXT_BG_COLOR_YN}
				, #{item.TEXT_UNDERLINE}
				, #{item.TEST_EDIT_YN}
				, #{item.TEXT_H_ALIGNMENT}
				, #{item.TEXT_V_ALIGNMENT}
				, #{item.TEXT_LINK_URL}
				, #{item.REMARKS}
				, #{item.DISPLAY_INDEX}
				, #{item.USE_YN}
				, #{item.USER_ID}
				, DATEADD(hh, ${item.GMT_TIME}, GETDATE())
				, #{item.PRINT_NO_FROM}
				, #{item.PRINT_NO_TO}
			)

/* interfaceMapper.insertHanjinPrintData : 한진 운송장 출력정보 저장 */
